"use client";

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";

import { cn } from "@/lib/utils";

// Controlled parents own the value: Base UI manages checked/indeterminate
// state internally, so this is a pure passthrough (no internal mirror).
//
// Checked, the box takes the button's material: blue vertical gradient, white
// gloss along the top edge, small blue throw underneath.
function Checkbox({
  className,
  indeterminate,
  ...props
}: CheckboxPrimitive.Root.Props) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      indeterminate={indeterminate}
      className={cn(
        "peer inline-flex items-center justify-center h-[1.125rem] w-[1.125rem] shrink-0 rounded-sm border border-border bg-input",
        "transition-[background,box-shadow,border-color] duration-base ease-out",
        "hover:border-ring/40",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "disabled:cursor-not-allowed disabled:opacity-45",
        "data-checked:border-transparent data-checked:bg-[image:var(--gradient-primary)] data-checked:text-primary-foreground data-checked:shadow-[var(--shadow-control)]",
        "data-indeterminate:border-transparent data-indeterminate:bg-[image:var(--gradient-primary)] data-indeterminate:text-primary-foreground data-indeterminate:shadow-[var(--shadow-control)]",
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="flex size-full items-center justify-center text-current"
      >
        {indeterminate ? (
          <svg
            viewBox="0 0 16 16"
            fill="none"
            aria-hidden="true"
            className="h-3 w-3"
          >
            <path
              d="M4 8h8"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
            />
          </svg>
        ) : (
          <svg
            viewBox="0 0 16 16"
            fill="none"
            aria-hidden="true"
            className="h-3 w-3"
          >
            <path
              d="M3.5 8.5l3 3 6-7"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        )}
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}
Checkbox.displayName = "Checkbox";

export { Checkbox };
